+/* Compact landscape layout: keep the fight controls clear of the HUD and dialogs. */
+@media (orientation:landscape) and (max-height:600px){
+ #game-shell{min-height:0;height:100dvh}
+ .mobile-controls{bottom:max(10px,env(safe-area-inset-bottom));left:max(14px,env(safe-area-inset-left));right:max(14px,env(safe-area-inset-right));align-items:flex-end}
+ .move-pad>button,.move-pad div button{width:42px;height:36px}
+ .move-pad div{gap:4px;margin-top:3px}
+ .action-pad{grid-template-columns:repeat(3,46px);gap:5px}
+ .action-pad .act{width:43px;height:40px;font-size:7px}
+ .fight-top{padding:10px 9% 0;grid-template-columns:1fr 58px 1fr;gap:12px}
+ .hud-name{font-size:17px}
+ .bar-frame{height:10px}
+ .hud-caption{font-size:6px;margin-top:4px}
+ .timer{font-size:31px}
+ .pause-btn{top:10px;right:max(10px,env(safe-area-inset-right));width:30px;height:30px}
+ .fight-toast{top:39%;font-size:clamp(22px,5vh,34px)}
+ .modal-card{width:min(500px,88vw);max-height:calc(100dvh - 24px);overflow-y:auto;padding:22px 28px}
+ .modal-card h2{font-size:38px;margin:8px 0}
+ .modal-card p{font-size:11px;margin-bottom:12px}
+ .modal-card .primary-btn{min-height:42px;margin:4px 0}
+ .modal-card .text-btn{margin-top:9px}
+ .result-score{padding:9px;margin:10px 0}
+ .how-card{width:min(650px,92vw)}
+ .how-card .controls-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 16px;margin:12px 0}
+ .how-card .controls-list div{gap:8px;font-size:10px}
+ .how-card .controls-list kbd{min-width:70px;padding:5px 6px;font-size:9px}
+ .how-card .small-note{line-height:1.4}
+}
+
+@media (prefers-reduced-motion:reduce){.modal-screen,.modal-card{transition-duration:.01ms}}
